window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-585152b9d4045ad7"]={"versions": [{"id": "FIG-585152b9d4045ad7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (AUTOSAR M2-Ebene, Package <code>M2::AUTOSARTemplates::AdaptivePlatform::General</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Modellierung der physischen Speicher- bzw. Dateipfadlokation (<code>uri</code>) eines durch ein logisches Modellelement (z. B. <code>Executable</code>, Konfigurationsdatei) repräsentierten Software-Artefakts innerhalb eines <code>SoftwareCluster</code>. Es dient der statischen Bindung zwischen ARXML-Designmodell und den realen Binär-/Dateiartefakten im Deployment-, Packaging- und Update-Prozess (UCM – Update and Config Management) der AUTOSAR Adaptive Platform.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt; Basisklassen: <code>MultilanguageReferrable</code>, <code>Referrable</code>, <code>ARObject</code>)</em></li>\n<li>Attribute:</li>\n<li><code>+ category: CategoryString [0..1]</code>: Klassifikation des Modellelements.</li>\n<li><code>+ uuid: String [0..1]</code>: Universally Unique Identifier zur modellweiten Nachverfolgbarkeit.</li>\n<li>Rolle: Dient als generischer Typ und Zielanker für Modellelemente, die durch physische Artefakte manifestiert werden.</li>\n<li><strong><code>ArtifactLocator</code></strong> <em>(konkret)</em></li>\n<li>Vererbung: Generalisiert von <code>Identifiable</code> (erbt <code>uuid</code>, <code>category</code> sowie Namens- und Referenzierungssemantik).</li>\n<li>Aggregation: Wird im Gesamtmodell durch <code>SoftwareCluster.artifactLocator</code> aggregiert.</li>\n<li>Attribute:</li>\n<li><code>+ uri: String [1]</code>: Eindeutiger URI-/Pfadbezeichner, der den physischen Speicherort des Artefakts angibt.</li>\n<li>Ausgehende Assoziation:</li>\n<li><code>+representedModelElement: Identifiable [0..1]</code>: Unidirektionale Referenz auf das logische Modellelement, dessen Artefaktlokation bestimmt wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Metamodell:</strong> Kein direkter dynamischer Kontrollfluss auf C++-API-Ebene.</li>\n<li><strong>Lebenszyklus- & Bindungsphasen:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Manifest-Generierung:</em> Werkzeuge ordnen erzeugte Binärdateien/Bibliotheken den Modellelementen über <code>ArtifactLocator</code> zu.</li>\n<li><em>Manifest-Finalisierung:</em> Validierungszeitpunkt von Konsistenzbedingungen (insbes. Kardinalitätsprüfungen).</li>\n<li><em>UCM-Installation / Execution Management:</em> Beim Einspielen eines Software-Pakets liest der Update and Config Manager den <code>uri</code> aus, extrahiert das Artefakt an den definierten Dateisystempfad und das Execution Management instanziiert bzw. startet die adressierte Binärdatei basierend auf der Verknüpfung zu <code>Executable</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte 1:1-Restriktion (<code>[constr_10380]{DRAFT}</code>):</strong></li>\n<li>Ein Modellelement (<code>Identifiable</code>), das Ziel einer Referenz in der Rolle <code>ArtifactLocator.representedModelElement</code> ist, darf in keinem anderen <code>ArtifactLocator</code> als Ziel referenziert werden.</li>\n<li>Diese Regel wird zum Zeitpunkt der Manifest-Finalisierung (<code>Manifest Creation Finished</code>) verbindlich forciert. Ein Modell, das versucht, demselben Modellelement mehrere unterschiedliche Lokationen zuzuordnen, ist ungültig.</li>\n<li><strong>Entwickler- & Tooling-Auswirkungen:</strong></li>\n<li><em>Generatoren/Build-Pipelines:</em> Müssen sicherstellen, dass pro Modellentität (z. B. Executable eines Adaptive Application Prozesses) genau eine physische Datei per relativem oder absolutem URI hinterlegt ist.</li>\n<li><em>Packaging:</em> Der im Attribut <code>uri</code> hinterlegte Pfad muss relativ zur Verzeichnisstruktur des Software-Cluster-Containers konsistent und deterministisch auflösbar sein.</li>\n</ul>"}, {"id": "FIG-4a9621efde340c5b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (AUTOSAR M2-Ebene, Package <code>M2::AUTOSARTemplates::AdaptivePlatform::General</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Modellierung der physischen Speicher- bzw. Dateipfadlokation (<code>uri</code>) eines durch ein logisches Modellelement (z. B. <code>Executable</code>, Konfigurationsdatei) repräsentierten Software-Artefakts innerhalb eines <code>SoftwareCluster</code>. Es dient der statischen Bindung zwischen ARXML-Designmodell und den realen Binär-/Dateiartefakten im Deployment-, Packaging- und Update-Prozess (UCM – Update and Config Management) der AUTOSAR Adaptive Platform.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt; Basisklassen: <code>MultilanguageReferrable</code>, <code>Referrable</code>, <code>ARObject</code>)</em></li>\n<li>Attribute:</li>\n<li><code>+ category: CategoryString [0..1]</code>: Klassifikation des Modellelements.</li>\n<li><code>+ uuid: String [0..1]</code>: Universally Unique Identifier zur modellweiten Nachverfolgbarkeit.</li>\n<li>Rolle: Dient als generischer Typ und Zielanker für Modellelemente, die durch physische Artefakte manifestiert werden.</li>\n<li><strong><code>ArtifactLocator</code></strong> <em>(konkret)</em></li>\n<li>Vererbung: Generalisiert von <code>Identifiable</code> (erbt <code>uuid</code>, <code>category</code> sowie Namens- und Referenzierungssemantik).</li>\n<li>Aggregation: Wird im Gesamtmodell durch <code>SoftwareCluster.artifactLocator</code> aggregiert.</li>\n<li>Attribute:</li>\n<li><code>+ uri: String [0..1]</code>: Eindeutiger URI-/Pfadbezeichner, der den physischen Speicherort des Artefakts angibt.</li>\n<li>Ausgehende Assoziation:</li>\n<li><code>+representedModelElement: Identifiable [0..1]</code>: Unidirektionale Referenz auf das logische Modellelement, dessen Artefaktlokation bestimmt wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statisches Metamodell:</strong> Kein direkter dynamischer Kontrollfluss auf C++-API-Ebene.</li>\n<li><strong>Lebenszyklus- & Bindungsphasen:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Manifest-Generierung:</em> Werkzeuge ordnen erzeugte Binärdateien/Bibliotheken den Modellelementen über <code>ArtifactLocator</code> zu.</li>\n<li><em>Manifest-Finalisierung:</em> Validierungszeitpunkt von Konsistenzbedingungen (insbes. Kardinalitätsprüfungen).</li>\n<li><em>UCM-Installation / Execution Management:</em> Beim Einspielen eines Software-Pakets liest der Update and Config Manager den <code>uri</code> aus, extrahiert das Artefakt an den definierten Dateisystempfad und das Execution Management instanziiert bzw. startet die adressierte Binärdatei basierend auf der Verknüpfung zu <code>Executable</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Strikte 1:1-Restriktion (<code>[constr_10380]{DRAFT}</code>):</strong></li>\n<li>Ein Modellelement (<code>Identifiable</code>), das Ziel einer Referenz in der Rolle <code>ArtifactLocator.representedModelElement</code> ist, darf in keinem anderen <code>ArtifactLocator</code> als Ziel referenziert werden.</li>\n<li>Diese Regel wird zum Zeitpunkt der Manifest-Finalisierung (<code>Manifest Creation Finished</code>) verbindlich forciert. Ein Modell, das versucht, demselben Modellelement mehrere unterschiedliche Lokationen zuzuordnen, ist ungültig.</li>\n<li><strong>Entwickler- & Tooling-Auswirkungen:</strong></li>\n<li><em>Generatoren/Build-Pipelines:</em> Müssen sicherstellen, dass pro Modellentität (z. B. Executable eines Adaptive Application Prozesses) genau eine physische Datei per relativem oder absolutem URI hinterlegt ist.</li>\n<li><em>Packaging:</em> Der im Attribut <code>uri</code> hinterlegte Pfad muss relativ zur Verzeichnisstruktur des Software-Cluster-Containers konsistent und deterministisch auflösbar sein.</li>\n</ul>"}], "trans": [{"from": "FIG-585152b9d4045ad7", "to": "FIG-4a9621efde340c5b", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ArtifactLocator</code>: Multiplizität des Attributs <code>+ uri</code> von <code>String</code> (obligatorisch, [1]) auf <code>String [0..1]</code> (optional) geändert.</li>\n</ul>"}]};
